-- script: lua


STEP_FRAMES = 30
TOTAL_STEPS = 63
MAX_LINES = 10

STATE_NOTICE_TERMINAL = 2
STATE_TERMINAL        = 3
STATE_GAME            = 4
STATE_FAIL            = 5
STATE_SUCCESS         = 6
-- table of frames when player needs to act
commands_template = {
 [2]="DOWN",[5]="UP",[8]="ACTION",[12]="UP",[15]="ACTION",
 [18]="DOWN",[21]="RIGHT",[24]="ACTION",[28]="ACTION",[32]="ACTION",
 [36]="ACTION",[40]="RIGHT",[43]="DOWN",[46]="DOWN",[49]="ACTION",
 [53]="RIGHT",[56]="RIGHT",[60]="DOWN",[62]="ACTION"
}
-- direction description for terminal
text_map = {
 UP="UP",
 DOWN="DOWN",
 RIGHT="RIGHT",
 ACTION="ACTION"
}

-- ======================
-- VARIABLES
-- ======================
show_title = true
title_timer = 300 -- 5 seconds at 60 FPS
state = STATE_NOTICE_TERMINAL
frame = 0
step = 1
timer = 0
commands = {}
log = {}
awaiting_input = false
current_cmd = nil
input_delay = 0
fail_logged = false
success_logged = false
music_playing = false

-- ======================
-- TEXT LOG FUNCTIONS
-- ======================
function add_line(t)
 table.insert(log, "> "..t)
 if #log > MAX_LINES then table.remove(log,1) end
end

function draw_log()
 for i=1,#log do
  print(log[i],4,20+(i-1)*10,12)
 end
end

function any_key()
 return btnp(0) or btnp(1) or btnp(2) or btnp(3)
     or btnp(4) or btnp(5) or btnp(6) or btnp(7)
end

-- ======================
-- INPUT CHECK (Arrow keys + Z/X + controller)
-- ======================
function check_input(cmd)
 -- YOUR CUSTOM MAPPING
 if cmd=="UP"     and (btnp(0) or btnp(4)) then return true end
 if cmd=="DOWN"   and (btnp(1) or btnp(4)) then return true end
 if cmd=="RIGHT"  and (btnp(3) or btnp(4)) then return true end
 if cmd=="ACTION" and (btnp(4) or btnp(5)) then return true end
 return false
end

-- ======================
-- RESET GAME
-- ======================
function reset_game()
 frame = 0
 step = 1
 commands = {}
 log = {}
 awaiting_input = false
 current_cmd = nil
 input_delay = 0
 fail_logged = false
 success_logged = false
 for k,v in pairs(commands_template) do commands[k] = v end
 add_line("QTE SEQUENCE STARTED")
 state = STATE_GAME
end

-- ======================
-- TIC FUNCTION
-- ======================
function TIC()
 cls(0)

 -- ======================
 -- PLAY MUSIC
 -- ======================
 if not music_playing then
     music(0)
     music_playing = true
 end

 -- ======================
 -- copyright and license notices
 -- ======================
 if show_title then
    print("Copyright (C) 2025 Daniel",0,10,12,false,1,true)
    print("Hanrahan Tools and Games",0,20,12,false,1,true)
    print("SPDX-License-Identifier: GPL-3.0-or-later",0,30,12,false,1,true)
    print("A copy of the GNU General Public License is",0,40,12,false,1,true)
    print("included in the file COPYING; if not, see",0,50,12,false,1,true)
    print("<https://www.gnu.org/licenses/>.",0,60,12,false,1,true)
    print("Information just about the stuff in this",0,70,12,false,1,true)
    print("software not covered by the GNU General",0,80,12,false,1,true)
    print("Public License version 3: This work is",0,90,12,false,1,true)
    print("licensed under Attribution-ShareAlike",0,100,12,false,1,true)
    print("4.0 International",0,110,12,false,1,true)
    print("PRESS Z TO START",80,120,12,false,1,true)

    title_timer = title_timer - 1
    if title_timer <=0 or btnp(4) then
        show_title=false
        state = STATE_NOTICE_TERMINAL
        timer = 0
    end
    return
 end

 -- ======================
 -- DEV TERMINAL NOTICE (exact wording)
 -- ======================
 if state == STATE_NOTICE_TERMINAL then
    print("This is a dev terminal if the TIC-80",4,56,12)
    print("could be connected to a video media",4,66,12)
    print("player playing the video for the game.",4,76,12)
    print("PRESS ANY KEY TO CONTINUE",28,96,11)
    if any_key() then state = STATE_TERMINAL timer = 0 end
    return
 end

 -- ======================
 -- TERMINAL BOOT
 -- ======================
 if state == STATE_TERMINAL then
    timer = timer + 1
    print("DEV TERMINAL",80,36,11)
    print("MEDIA STREAM READY",40,66,12)
    if timer > 180 then reset_game() end
    return
 end

 -- ======================
 -- TEXT-BASED QTE
 -- ======================
 if state == STATE_GAME then
    frame = frame + 1
    step = math.floor(frame / STEP_FRAMES) + 1

    if step > TOTAL_STEPS then state = STATE_SUCCESS return end

    if not awaiting_input then
        local cmd = commands[step]
        if cmd then
            current_cmd = cmd
            awaiting_input = true
            input_delay = 1
            add_line("FRAME "..step)
            add_line(text_map[cmd])
        end
    end

    if awaiting_input then
        if input_delay > 0 then
            input_delay = input_delay - 1
        elseif check_input(current_cmd) then
            add_line("INPUT ACCEPTED")
            awaiting_input = false
            current_cmd = nil
            commands[step] = nil
        elseif frame % STEP_FRAMES == STEP_FRAMES-1 then
            state = STATE_FAIL
        end
    end

    draw_log()
    return
 end

 -- ======================
 -- FAIL
 -- ======================
 if state == STATE_FAIL then
    if not fail_logged then
        add_line("TERMINAL DESYNC")
        add_line("STREAM FAILED")
        fail_logged = true
    end
    draw_log()
    print("PRESS Z TO RETRY",48,116,8)
    if btnp(4) then reset_game() end
    return
 end

 -- ======================
 -- SUCCESS
 -- ======================
 if state == STATE_SUCCESS then
    if not success_logged then
        add_line("STREAM COMPLETE")
        add_line("SYNC SUCCESSFUL")
        success_logged = true
    end
    draw_log()
    return
 end
end

